sources.src/components/editors/EndMessagePlaybac:
import { Toggle } from '../common/Toggle';

function playbackSummaryText(summary) {
  if (summary.total === 0) {
    return 'Le réglage s’appliquera aux histoires du pack.';
  }
  if (summary.mode === 'mixed') {
    const stays = summary.stays ? ` · ${summary.stays} restent sur le message` : '';
    return `${summary.waitingOk} histoires attendent un appui sur OK · ${summary.autoPlay} continuent automatiquement${stays}`;
  }
  if (summary.mode === 'wait') {
    return `${summary.total} histoire${summary.total > 1 ? 's attendent' : ' attend'} un appui sur OK.`;
  }
  return `${summary.total} histoire${summary.total > 1 ? 's continuent' : ' continue'} automatiquement.`;
}

function playbackExplanationText(mode) {
  if (mode === 'mixed') {
    return 'Certaines histoires continuent automatiquement, d’autres attendent un appui sur OK.';
  }
  if (mode === 'wait') {
    return 'L’enfant reste sur le message de fin tant qu’il n’a pas appuyé sur OK.';
  }
  return 'La destination suivante s’ouvre dès la fin du message.';
}

export function EndMessagePlaybackControl({ summary, onChange }) {
  const waitForOk = summary.mode === 'wait';
  const mixed = summary.mode === 'mixed';

  return (
    <div className="end-message-playback-control">
      <div className="end-message-playback-choice">
        <button
          type="button"
          className={`end-message-playback-label${summary.mode === 'auto' ? ' is-active' : ''}`}
          onClick={() => onChange?.(true)}
        >
          Automatiquement
        </button>
        <Toggle
          on={waitForOk}
          mixed={mixed}
          onChange={(nextWaitForOk) => onChange?.(!nextWaitForOk)}
          ariaLabel={mixed
            ? 'Réglage mixte importé ; cliquer pour faire attendre un appui sur OK à toutes les histoires'
            : 'Attendre un appui sur OK après le message de fin'}
        />
        <button
          type="button"
          className={`end-message-playback-label${summary.mode === 'wait' ? ' is-active' : ''}`}
          onClick={() => onChange?.(false)}
        >
          Après appui sur OK
        </button>
      </div>
      <div className="end-message-playback-explanation">
        {playbackExplanationText(summary.mode)}
      </div>
      <div className={`end-message-playback-summary${mixed ? ' is-mixed' : ''}`}>
        {mixed ? <strong>Réglage mixte importé</strong> : null}
        <span>{playbackSummaryText(summary)}</span>
      </div>
    </div>
  );
}

sources.src/components/editors/EndNodeEditor.jsx:
import { Toggle } from '../common/Toggle';
import { AudioField } from './AudioField';
import { NavigationTargetSelect } from './story/storyUtils';
import { Trash2 } from '../icons/LucideLocal';
import {
  collectEndMessagePresentations,
  getPackStartReturnLabel,
} from '../../store/generatedNavigation';
import {
  getEffectiveEndMessageControlState,
  summarizeEndMessagePlayback,
} from '../../store/endMessagePresentation';
import { EndMessagePlaybackControl } from './EndMessagePlaybackControl';
import './EditorPanel.css';

export function EndNodeEditor({
  endNodeName = 'Message de fin',
  nightModeAudio,
  nightModeActive,
  nightModeReturn,
  nightModeHomeReturn,
  projectName,
  allMenus = [],
  allStories = [],
  onUpdateNightModeAudio,
  onUpdateNightMode,
  onUpdateNightModeReturn,
  onUpdateNightModeHomeReturn,
  onUpdateEndMessageAutoplay,
  onUpdateEndNodeName,
  onRemove,
  project = null,
  onExamineStory,
  onAttachStory,
}) {
  const hasAudio = typeof nightModeAudio === 'string' && nightModeAudio.trim().length > 0;
  const packStartReturnLabel = getPackStartReturnLabel(project);
  const presentations = collectEndMessagePresentations(project);
  const globalStories = presentations.filter((item) => item.presentationKind === 'global');
  const localStories = presentations.filter((item) => item.presentationKind === 'local_prompt' || item.presentationKind === 'local_sequence');
  const controlStates = globalStories.map((item) => getEffectiveEndMessageControlState(
    item.navigation.endMessage.controls,
    item.effectiveHome,
  ));
  const playbackSummary = summarizeEndMessagePlayback(
    controlStates,
    project?.globalOptions?.endMessageAutoplay ?? true,
  );

  return (
    <>
      <div className="card">
        <div className="card-title-row">
          <div className="card-title">Message de fin</div>
          <div className="card-copy card-copy--inline">
            Audio joué après chaque histoire, avant la destination finale.
          </div>
        </div>

        <div className="field-row">
          <span className="field-label">Nom</span>
          <input
            className="field-input"
            value={endNodeName}
            onChange={(event) => onUpdateEndNodeName?.(event.target.value)}
            placeholder="Message de fin"
          />
        </div>

        <AudioField
          label="Audio de fin d'histoire"
          file={nightModeAudio}
          ttsTextSuggestion={endNodeName || ''}
          ttsFilenameHint={`fin-histoire-${projectName || 'projet'}`}
          xttsTarget={{ kind: 'root', field: 'nightModeAudio' }}
          onPick={(file) => onUpdateNightModeAudio(file)}
          onClear={() => onUpdateNightModeAudio(null)}
        />

        {!hasAudio && (
          <div className="info-box warn">
            Audio requis pour la génération.
          </div>
        )}
        {localStories.length > 0 && (
          <div className="end-node-local-list">
            <span className="field-label">Fins locales</span>
            {localStories.map((item) => (
              <div key={item.entry.id} className="end-node-local-list-row">
                <button type="button" className="link-button" onClick={() => onExamineStory?.(item.entry.id)}>
                  Examiner {item.entry.name || 'cette histoire'}
                </button>
                <button type="button" className="link-button" onClick={() => onAttachStory?.(item.entry.id)}>
                  Rattacher au message du pack
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="card">
        <div className="card-title-row">
          <div className="card-title">Pendant la lecture</div>
        </div>
        <div className="editor-setting-stack">
          <div className="editor-setting-row end-node-setting-row">
            <div className="editor-setting-copy end-node-setting-copy">
              <div className="editor-setting-title">Bouton Accueil</div>
              <div className="editor-setting-desc">
                Destination si l'enfant appuie sur Accueil pendant le message de fin.
              </div>
            </div>
            <div className="editor-setting-control">
              <NavigationTargetSelect
                value={nightModeHomeReturn ?? ''}
                onChange={(value) => onUpdateNightModeHomeReturn?.(value)}
                allMenus={allMenus}
                allStories={allStories}
                currentStoryId={null}
                emptyLabel={packStartReturnLabel}
                includeStoryPlay={false}
                flagMissingValue
              />
            </div>
          </div>
        </div>
      </div>

      <div className="card">
        <div className="card-title-row">
          <div className="card-title">Après la lecture</div>
        </div>
        <div className="editor-setting-stack">
          <div className="editor-setting-row end-node-setting-row end-node-playback-row">
            <div className="editor-setting-copy">
              <div className="editor-setting-title">Quand passer à la suite ?</div>
              <div className="editor-setting-desc">
                Le retour vers la destination configurée ci-dessous s’effectue dès la fin du message ou après un appui sur OK.
              </div>
            </div>
            <EndMessagePlaybackControl
              summary={playbackSummary}
              onChange={onUpdateEndMessageAutoplay}
            />
          </div>
          <div className="editor-setting-row end-node-setting-row">
            <div className="editor-setting-copy end-node-setting-copy">
              <div className="editor-setting-title">Retour après le message</div>
              <div className="editor-setting-desc">
                {nightModeReturn
                  ? 'Cette destination remplace les réglages individuels des histoires.'
                  : 'Chaque histoire utilise sa destination individuelle, héritée ou par défaut.'}
              </div>
            </div>
            <div className="editor-setting-control">
              <NavigationTargetSelect
                value={nightModeReturn ?? ''}
                onChange={(value) => onUpdateNightModeReturn?.(value)}
                allMenus={allMenus}
                allStories={allStories}
                currentStoryId={null}
                emptyLabel="Selon chaque histoire"
                flagMissingValue
              />
            </div>
          </div>
        </div>
      </div>

      <div className="card">
        <div className="card-title-row">
          <div className="card-title">Réglage du message de fin</div>
        </div>
        <div className="editor-setting-stack">
          <div className="editor-setting-row is-toggle-row end-node-setting-row end-node-toggle-row">
            <Toggle on={nightModeActive} onChange={onUpdateNightMode} />
            <div className="editor-setting-copy end-node-setting-copy">
              <div className="editor-setting-title">Activer le mode nuit</div>
            </div>
          </div>
        </div>
      </div>

      <div className="card card--danger card--danger-compact">
        <div className="card-danger-row">
          <button
            className="card-danger-trash"
            type="button"
            onClick={() => onRemove?.()}
            aria-label="Supprimer le message de fin"
          >
            <Trash2 className="card-danger-icon" />
          </button>
          <span className="card-danger-title">Supprimer le message de fin</span>
          <p className="card-danger-desc">
            Retire le message de fin du pack. Les histoires ne joueront plus de message commun à leur conclusion. Désactive aussi le mode nuit.
          </p>
        </div>
      </div>
    </>
  );
}

