import { AudioField } from '../AudioField';
import { ImageField } from '../ImageField';
import { useErrorDialog } from '../../common/Dialog';
import { Toggle } from '../../common/Toggle';
import { Tooltip } from '../../common/Tooltip';
import { Button } from '../../common/Button';
import { MoveDown, MoveUp, Trash2 } from '../../icons/LucideLocal';
import {
  CONTROL_DEFS,
  SEQUENCE_CONTROL_DEFAULTS,
  NavigationTargetSelect,
  normalizeSequenceStep,
  resolveNavigationTargetId,
} from './storyUtils';

export function EndSequenceEditor({
  node,
  parentMenuId,
  steps,
  homeStep,
  allMenus,
  allStories,
  packStartReturnLabel = 'Retour à la couverture du pack',
  onUpdate,
}) {
  const { showConfirmDialog } = useErrorDialog();

  function updateSequence(nextSteps) {
    onUpdate({ afterPlaybackSequence: nextSteps.map((s, i) => normalizeSequenceStep(s, i)) });
  }

  function updateStep(index, fields) {
    updateSequence(steps.map((s, i) => i === index ? normalizeSequenceStep({ ...s, ...fields }, i) : s));
  }

  function updateStepControls(index, key, value) {
    const step = steps[index];
    if (!step) return;
    updateStep(index, {
      controlSettings: { ...SEQUENCE_CONTROL_DEFAULTS, ...(step.controlSettings ?? {}), [key]: value },
    });
  }

  function moveStep(index, direction) {
    const target = index + direction;
    if (target < 0 || target >= steps.length) return;
    const next = [...steps];
    const [step] = next.splice(index, 1);
    next.splice(target, 0, step);
    updateSequence(next);
  }

  async function deleteStep(index) {
    const step = steps[index];
    if (!step) return;
    const confirmed = await showConfirmDialog({
      title: 'Confirmer la suppression',
      message: `Supprimer l'étape "${step.name || `Étape ${index + 1}`}" ?`,
      okLabel: 'Supprimer',
      okKind: 'danger',
    });
    if (!confirmed) return;
    updateSequence(steps.filter((_, i) => i !== index));
  }

  function addStep() {
    updateSequence([
      ...steps,
      normalizeSequenceStep({
        name: `Étape ${steps.length + 1}`,
        controlSettings: {
          ...SEQUENCE_CONTROL_DEFAULTS,
          autoplay: steps.length === 0,
          ok: true,
        },
      }, steps.length),
    ]);
  }

  function updateHomeStep(fields) {
    onUpdate({
      afterPlaybackHomeStep: normalizeSequenceStep({
        ...(homeStep ?? {
          name: "Écran d'attente",
          controlSettings: { ...SEQUENCE_CONTROL_DEFAULTS, ok: true },
        }),
        ...fields,
      }, 0),
    });
  }

  function updateHomeStepControls(key, value) {
    updateHomeStep({
      controlSettings: {
        ...SEQUENCE_CONTROL_DEFAULTS,
        ...(homeStep?.controlSettings ?? {}),
        [key]: value,
      },
    });
  }

  return (
    <div>
      <div className="sequence-list">
        {steps.map((step, index) => {
          const controls = { ...SEQUENCE_CONTROL_DEFAULTS, ...(step.controlSettings ?? {}) };
          const isLast = index === steps.length - 1;
          const homeSelectValue = step.homeNone ? '__none__' : (step.homeTarget ?? '');
          const okTargetId = resolveNavigationTargetId(step.okTarget, parentMenuId ?? null);
          const continuationMenu = isLast
            ? allMenus.find((m) => m.id === okTargetId && m.importedContinuation)
            : null;

          return (
            <div className="sequence-step" key={step.id}>
              <div className="sequence-step-head">
                <div className="sequence-step-index">{index + 1}</div>
                <input
                  className="field-input sequence-step-name"
                  value={step.name || ''}
                  onChange={(e) => updateStep(index, { name: e.target.value })}
                  placeholder={`Étape ${index + 1}`}
                />
                <div className="sequence-step-actions">
                  <Tooltip text="Monter">
                    <Button
                      size="sm"
                      className="sequence-icon-btn"
                      disabled={index === 0}
                      onClick={() => moveStep(index, -1)}
                    >
                      <MoveUp className="sequence-icon" />
                    </Button>
                  </Tooltip>
                  <Tooltip text="Descendre">
                    <Button
                      size="sm"
                      className="sequence-icon-btn"
                      disabled={isLast}
                      onClick={() => moveStep(index, 1)}
                    >
                      <MoveDown className="sequence-icon" />
                    </Button>
                  </Tooltip>
                  <Tooltip text="Supprimer cette étape">
                    <Button
                      size="sm"
                      className="sequence-icon-btn sequence-icon-btn--danger"
                      onClick={() => deleteStep(index)}
                    >
                      <Trash2 className="sequence-icon" />
                    </Button>
                  </Tooltip>
                </div>
              </div>

              <AudioField
                label={`Audio — étape ${index + 1}`}
                file={step.audio}
                ttsTextSuggestion={step.name || node.name || ''}
                ttsFilenameHint={`fin-${index + 1}-${node.name || 'histoire'}`}
                xttsTarget={{ kind: 'storySequence', entryId: node.id, stepId: step.id, field: 'audio' }}
                onPick={(file) => updateStep(index, { audio: file })}
                onClear={() => updateStep(index, { audio: null })}
              />

              <div className="sequence-controls">
                {CONTROL_DEFS.map(({ key, label, def }) => (
                  <label key={key} className="sequence-control sequence-control--toggle-left">
                    <Toggle
                      on={controls[key] ?? def}
                      onChange={(v) => updateStepControls(index, key, v)}
                    />
                    <span className="sequence-control-title">{label}</span>
                  </label>
                ))}
              </div>

              <div className="sequence-targets">
                {isLast ? (
                  <>
                    <div className="sequence-destination-row">
                      <div className="sequence-destination-copy">
                        <span className="sequence-destination-title">Destination après cette étape</span>
                      </div>
                      <NavigationTargetSelect
                        value={step.okTarget ?? ''}
                        onChange={(value) => updateStep(index, { okTarget: value })}
                        allMenus={allMenus}
                        allStories={allStories}
                        currentStoryId={node.id}
                        emptyLabel="Comme à la fin de l'histoire"
                      />
                    </div>
                    {continuationMenu ? (
                      <div className="sequence-note">
                        Cette étape mène vers la continuation importée "{continuationMenu.name || 'Suite'}"
                        {continuationMenu.importedContinuation?.sourceStoryName
                          ? ` depuis ${continuationMenu.importedContinuation.sourceStoryName}`
                          : ''}.
                      </div>
                    ) : null}
                  </>
                ) : (
                  <div className="sequence-next-note">Bouton OK enchaîne vers l'étape suivante.</div>
                )}
                <div className="sequence-destination-row">
                  <div className="sequence-destination-copy">
                    <span className="sequence-destination-title">Destination du bouton Accueil</span>
                  </div>
                  <NavigationTargetSelect
                    value={homeSelectValue}
                    onChange={(value) => {
                      if (value === '__none__') {
                        updateStep(index, { homeNone: true, homeTarget: null, homeFollowsOk: false });
                      } else {
                        updateStep(index, { homeNone: false, homeTarget: value, homeFollowsOk: false });
                      }
                    }}
                    allMenus={allMenus}
                    allStories={allStories}
                    currentStoryId={node.id}
                    includeNone
                    noneLabel={packStartReturnLabel}
                    emptyLabel="Comme à la fin de l'histoire"
                    includeStoryPlay={false}
                  />
                </div>
                <label className="sequence-control sequence-control--toggle-left">
                  <Toggle
                    on={!!step.homeFollowsOk}
                    onChange={(v) => updateStep(index, {
                      homeFollowsOk: v,
                      homeNone: false,
                      homeTarget: v ? null : step.homeTarget,
                    })}
                  />
                  <span className="sequence-control-title">Même destination que OK</span>
                </label>
              </div>
            </div>
          );
        })}
      </div>

      <div className="sequence-footer">
        <Button onClick={addStep}>
          Ajouter une étape
        </Button>
      </div>

      {/* Réaction au bouton Accueil (afterPlaybackHomeStep) */}
      <div className="end-summary" style={{ marginTop: 12 }}>
        <div>
          <div className="end-summary-title">Réaction au bouton Accueil</div>
          <div className="end-summary-copy">
            Étape jouée si l'enfant appuie sur le bouton Accueil pendant l'histoire, avant qu'elle ne se termine.
          </div>
          {homeStep && node.controlSettings?.home === false && (
            <div className="end-summary-copy">
              Accueil est désactivé : cette réaction ne sera pas jouée.
            </div>
          )}
        </div>
        {homeStep ? (
          <Tooltip text="Retirer la réaction Accueil">
            <button
              type="button"
              className="story-prompt-trash"
              onClick={() => onUpdate({ afterPlaybackHomeStep: null })}
              aria-label="Retirer la réaction Accueil"
            >
              <Trash2 className="card-danger-icon" />
            </button>
          </Tooltip>
        ) : (
          <Button size="sm" onClick={() => updateHomeStep({})}>
            Ajouter
          </Button>
        )}
      </div>

      {homeStep ? (
        <div className="sequence-step" style={{ marginTop: 10 }}>
          <div className="sequence-step-head">
            <div className="sequence-step-index">⏸</div>
            <input
              className="field-input sequence-step-name"
              value={homeStep.name || ''}
              onChange={(e) => updateHomeStep({ name: e.target.value })}
              placeholder="Réaction au bouton Accueil"
            />
          </div>
          <AudioField
            label="Audio joué quand l'enfant appuie sur Accueil"
            file={homeStep.audio}
            ttsTextSuggestion={homeStep.name || node.name || ''}
            ttsFilenameHint={`attente-${node.name || 'histoire'}`}
            xttsTarget={{ kind: 'storyHomeStep', entryId: node.id, field: 'audio' }}
            onPick={(file) => updateHomeStep({ audio: file })}
            onClear={() => updateHomeStep({ audio: null })}
          />
          <ImageField
            fieldId={`${node.id}:homeStep:image`}
            label="Image affichée pendant la réaction Accueil"
            file={homeStep.image}
            onPick={(file) => updateHomeStep({ image: file })}
            onClear={() => updateHomeStep({ image: null })}
          />
          <div className="sequence-controls">
            {CONTROL_DEFS.map(({ key, label, def }) => (
              <label key={key} className="sequence-control sequence-control--toggle-left">
                <Toggle
                  on={homeStep.controlSettings?.[key] ?? def}
                  onChange={(v) => updateHomeStepControls(key, v)}
                />
                <span className="sequence-control-title">{label}</span>
              </label>
            ))}
          </div>
          <div className="sequence-destination-row">
            <div className="sequence-destination-copy">
              <span className="sequence-destination-title">Destination du bouton Accueil</span>
            </div>
            <NavigationTargetSelect
              value={homeStep.homeNone ? '__none__' : (homeStep.homeTarget ?? '')}
              onChange={(value) => {
                if (value === '__none__') {
                  updateHomeStep({ homeNone: true, homeTarget: null, homeFollowsOk: false });
                } else {
                  updateHomeStep({ homeNone: false, homeTarget: value, homeFollowsOk: false });
                }
              }}
              allMenus={allMenus}
              allStories={allStories}
              currentStoryId={node.id}
              includeNone
              noneLabel={packStartReturnLabel}
              emptyLabel="Comme à la fin de l'histoire"
              includeStoryPlay={false}
            />
          </div>
          <label className="sequence-control sequence-control--toggle-left" style={{ marginTop: 8 }}>
            <Toggle
              on={!!homeStep.homeFollowsOk}
              onChange={(v) => updateHomeStep({
                homeFollowsOk: v,
                homeNone: false,
                homeTarget: v ? null : homeStep.homeTarget,
              })}
            />
            <span className="sequence-control-title">Même destination que OK</span>
          </label>
        </div>
      ) : null}
    </div>
  );
}

import { useEffect, useId, useMemo, useRef, useState } from 'react';
import {
  NAV_TARGET_NEXT_STORY,
  decodeNavigationMenuId,
  decodeNavigationStoryId,
  encodeMenuNavigationTarget,
  encodeStoryHomeStepNavigationTarget,
  encodeStoryNavigationTarget,
  encodeStoryPlayNavigationTarget,
  isCurrentMenuNavigationTarget,
  isNextStoryNavigationTarget,
  isRootNavigationTarget,
  isStoryNavigationTarget,
  normalizeNavigationTarget,
} from '../../../store/navigationTargets';
import { CircleX, FolderOpen, Link2, Music, Play } from '../../icons/LucideLocal';

export const NAV_ROOT_LABEL = 'Menu racine';

export function generatedTargetIdToSelectValue(targetId) {
  if (!targetId || isRootNavigationTarget(targetId)) return '';
  if (isStoryNavigationTarget(targetId) || isNextStoryNavigationTarget(targetId)) return targetId;
  return encodeMenuNavigationTarget(targetId);
}

const NAV_ICON_BY_KIND = {
  default: Link2,
  none: CircleX,
  root: FolderOpen,
  menu: FolderOpen,
  story: Music,
  story_play: Play,
  story_home_step: Music,
};

function iconForKind(kind) {
  return NAV_ICON_BY_KIND[kind] ?? null;
}

function buildNavigationTargetOptions({
  value,
  allMenus = [],
  allStories = [],
  currentStoryId = null,
  allowCurrentStory = false,
  includeNone = false,
  noneLabel = 'Retour à la couverture du pack',
  emptyLabel = 'Choisir une destination',
  includeDefault = true,
  includeNextStory = true,
  includeStoryPlay = true,
  flagMissingValue = false,
}) {
  const options = [];
  if (value === '__mixed__') {
    options.push({
      value: '__mixed__',
      label: 'Valeurs mixtes — ne pas modifier',
      kind: 'default',
      disabled: true,
    });
  }
  if (includeDefault) {
    options.push({ value: '', label: emptyLabel, kind: 'default' });
  }
  if (includeNone) options.push({ value: '__none__', label: noneLabel, kind: 'none' });
  if (includeNextStory) {
    options.push({ value: NAV_TARGET_NEXT_STORY, label: 'Histoire suivante', kind: 'story' });
  }
  for (const menu of allMenus) {
    options.push({
      value: encodeMenuNavigationTarget(menu.id),
      label: menu.name || '(sans nom)',
      kind: 'menu',
    });
  }
  const selectableStories = allStories.filter((s) => allowCurrentStory || s.id !== currentStoryId);
  for (const story of selectableStories) {
    options.push({
      value: encodeStoryNavigationTarget(story.id),
      label: story.name || '(sans nom)',
      kind: 'story',
    });
  }
  if (includeStoryPlay) {
    for (const story of selectableStories) {
      options.push({
        value: encodeStoryPlayNavigationTarget(story.id),
        label: `Lecture directe - ${story.name || '(sans nom)'}`,
        kind: 'story_play',
      });
    }
  }
  for (const story of allStories.filter((s) => s.id !== currentStoryId && s.hasAfterPlaybackHomeStep)) {
    options.push({
      value: encodeStoryHomeStepNavigationTarget(story.id),
      label: `Retour de fin - ${story.name || '(sans nom)'}`,
      kind: 'story_home_step',
    });
  }
  // Une destination dont l'histoire ou le dossier a été supprimé reste affichée
  // comme telle, jamais confondue avec le choix par défaut de la ligne vide.
  if (flagMissingValue && isMissingNavigationValue(value, allMenus, allStories)) {
    options.unshift({ value, label: 'Destination supprimée — à choisir', kind: 'none', disabled: true });
  }
  return options;
}

function isMissingNavigationValue(value, allMenus, allStories) {
  const normalized = normalizeNavigationTarget(value);
  if (!normalized || value === '__mixed__' || value === '__none__') return false;
  if (isRootNavigationTarget(normalized) || isCurrentMenuNavigationTarget(normalized)) return false;
  if (isNextStoryNavigationTarget(normalized)) return false;
  if (isStoryNavigationTarget(normalized)) {
    const storyId = decodeNavigationStoryId(normalized);
    return !allStories.some((story) => story.id === storyId);
  }
  const menuId = decodeNavigationMenuId(normalized);
  return !allMenus.some((menu) => menu.id === menuId);
}

export const CONTROL_DEFS = [
  { key: 'autoplay', label: 'Lecture automatique', def: true },
  { key: 'ok',       label: 'Bouton OK',            def: true },
  { key: 'home',     label: 'Bouton Accueil',        def: true },
  { key: 'pause',    label: 'Bouton pause',          def: false },
  { key: 'wheel',    label: 'Molette',               def: false },
];

export const SEQUENCE_CONTROL_DEFAULTS = {
  autoplay: true,
  ok: false,
  home: true,
  pause: false,
  wheel: false,
};

export function normalizeSequenceStep(step = {}, index = 0) {
  const controls = step.controlSettings ?? {};
  return {
    id: step.id || crypto.randomUUID(),
    name: step.name || `Étape ${index + 1}`,
    audio: step.audio ?? null,
    image: step.image ?? null,
    controlSettings: { ...SEQUENCE_CONTROL_DEFAULTS, ...controls },
    okTarget: normalizeNavigationTarget(step.okTarget),
    okChoiceTargets: Array.isArray(step.okChoiceTargets)
      ? step.okChoiceTargets.map(normalizeNavigationTarget).filter(Boolean)
      : [],
    homeTarget: normalizeNavigationTarget(step.homeTarget),
    homeFollowsOk: !!step.homeFollowsOk,
    homeNone: !!step.homeNone,
  };
}

export function resolveNavigationTargetId(target, currentMenuId = null) {
  const normalized = normalizeNavigationTarget(target);
  if (!normalized) return null;
  if (isRootNavigationTarget(normalized)) return 'root';
  if (isCurrentMenuNavigationTarget(normalized)) return currentMenuId ?? null;
  if (isNextStoryNavigationTarget(normalized)) return NAV_TARGET_NEXT_STORY;
  if (isStoryNavigationTarget(normalized)) return normalized;
  return decodeNavigationMenuId(normalized);
}

// Calcule le texte de destination effective pour les résumés de parcours.
// - Pour un value vide ou "root" → renvoie le défaut résolu (ex: "Quelle histoire...").
// - Pour "next_story" → renvoie soit le nom de l'histoire suivante si entry est fourni, soit la mention contextuelle.
// - Pour un menu/story explicite → null (pas de hint nécessaire).
//
// L'appelant passe `emptyResolvedLabel` qui décrit ce que "vide" signifie dans son contexte
// (héritage parent vs premier élément du pack vs etc).
export function getNavigationSelectHint({
  value,
  emptyResolvedLabel = null,
  entry = null,
  parentMenu = null,
  project = null,
}) {
  const normalized = normalizeNavigationTarget(value);
  if (!normalized) return emptyResolvedLabel;
  if (isRootNavigationTarget(normalized)) {
    const def = project?.rootEntries?.[0];
    if (!def) return 'Aucune entrée dans le pack';
    return `${def.name || '(sans nom)'} (premier élément du pack)`;
  }
  if (isNextStoryNavigationTarget(normalized)) {
    if (!entry) return 'Histoire suivante selon l\'histoire source';
    const siblings = parentMenu ? (parentMenu.children ?? []) : (project?.rootEntries ?? []);
    const idx = siblings.findIndex((s) => s.id === entry.id);
    const next = idx >= 0 ? siblings.slice(idx + 1).find((s) => s.type === 'story') : null;
    if (next) return next.name || '(sans nom)';
    // Fallback Rust : si pas d'histoire suivante, retour vers le parent
    return parentMenu ? `${parentMenu.name || '(sans nom)'} (parent)` : NAV_ROOT_LABEL;
  }
  // Explicite — la valeur affichée dans le select est déjà la destination
  return null;
}

export function NavigationTargetSelect({
  value,
  onChange,
  allMenus,
  allStories,
  currentStoryId,
  allowCurrentStory = false,
  includeNone = false,
  noneLabel = 'Retour à la couverture du pack',
  emptyLabel = 'Choisir une destination',
  includeDefault = true,
  resolvedDefaultValue = null,
  resolvedDefaultLabel = null,
  resolvedDefaultKind = 'default',
  hideDefaultWhenResolved = false,
  style,
  includeNextStory = true,
  includeStoryPlay = true,
  flagMissingValue = false,
  size = 'default',
}) {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);
  const rootRef = useRef(null);
  const listboxId = useId();
  const rawSelectedValue = value ?? '';
  const normalizedResolvedValue = resolvedDefaultValue
    ? normalizeNavigationTarget(resolvedDefaultValue)
    : null;
  const baseOptions = useMemo(
    () => buildNavigationTargetOptions({
      value: rawSelectedValue,
      allMenus,
      allStories,
      currentStoryId,
      allowCurrentStory,
      includeNone,
      noneLabel,
      emptyLabel,
      includeDefault,
      includeNextStory,
      includeStoryPlay,
      flagMissingValue,
    }),
    [
      rawSelectedValue,
      allMenus,
      allStories,
      currentStoryId,
      allowCurrentStory,
      includeNone,
      noneLabel,
      emptyLabel,
      includeDefault,
      includeNextStory,
      includeStoryPlay,
      flagMissingValue,
    ],
  );
  // Un « vrai » choix correspond à une ligne concrète de la liste (menu, histoire,
  // « Histoire suivante »…). Les cibles virtuelles (racine, dossier courant) et la
  // valeur vide n'ont pas de ligne dédiée : on les résout vers leur destination réelle
  // pour ne jamais afficher un libellé abstrait dans le déclencheur.
  const rawMatchesConcreteOption = !!rawSelectedValue
    && baseOptions.some((option) => option.value === rawSelectedValue && option.value !== '');
  const useResolvedValue = !!(normalizedResolvedValue && !rawMatchesConcreteOption);
  const selectedValue = useResolvedValue ? normalizedResolvedValue : rawSelectedValue;
  const hideResolvedDefault = !!(includeDefault && hideDefaultWhenResolved && useResolvedValue);
  const options = useMemo(
    () => (hideResolvedDefault
      ? baseOptions.filter((option) => option.value !== '')
      : baseOptions),
    [baseOptions, hideResolvedDefault],
  );
  const resolvedSelectedOption = useResolvedValue
    ? {
      value: normalizedResolvedValue,
      label: resolvedDefaultLabel || emptyLabel,
      kind: resolvedDefaultKind || 'default',
    }
    : null;
  const selectableOptions = useMemo(
    () => options.filter((option) => !option.disabled),
    [options],
  );
  const selectedOption = options.find((option) => option.value === selectedValue)
    ?? resolvedSelectedOption
    ?? options.find((option) => option.value === '')
    ?? options[0];
  const SelectedIcon = iconForKind(selectedOption?.kind);

  useEffect(() => {
    if (!open) return undefined;
    const handlePointerDown = (event) => {
      if (!rootRef.current?.contains(event.target)) setOpen(false);
    };
    document.addEventListener('pointerdown', handlePointerDown);
    return () => document.removeEventListener('pointerdown', handlePointerDown);
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const selectedIndex = selectableOptions.findIndex((option) => option.value === selectedValue);
    setActiveIndex(Math.max(0, selectedIndex));
  }, [open, selectableOptions, selectedValue]);

  useEffect(() => {
    if (!open) return;
    const activeOption = rootRef.current?.querySelector(`[data-option-index="${activeIndex}"]`);
    activeOption?.scrollIntoView({ block: 'nearest' });
  }, [open, activeIndex]);

  const selectOption = (option) => {
    if (!option || option.disabled) return;
    onChange(option.value || null);
    setOpen(false);
  };

  const moveActive = (delta) => {
    if (selectableOptions.length === 0) return;
    setActiveIndex((current) => (current + delta + selectableOptions.length) % selectableOptions.length);
  };

  const handleKeyDown = (event) => {
    if (!open) {
      if (event.key === 'ArrowDown' || event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        setOpen(true);
      }
      return;
    }
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      moveActive(1);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      moveActive(-1);
    } else if (event.key === 'Home') {
      event.preventDefault();
      setActiveIndex(0);
    } else if (event.key === 'End') {
      event.preventDefault();
      setActiveIndex(Math.max(0, selectableOptions.length - 1));
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      selectOption(selectableOptions[activeIndex]);
    } else if (event.key === 'Escape') {
      event.preventDefault();
      setOpen(false);
    }
  };

  const activeOptionId = open && selectableOptions[activeIndex]
    ? `${listboxId}-option-${activeIndex}`
    : undefined;

  return (
    <div className="navigation-target-select" style={style}>
      <div
        ref={rootRef}
        className={`navigation-listbox ${open ? 'is-open' : ''} ${size === 'compact' ? 'is-compact' : ''}`}
      >
        <button
          type="button"
          className="navigation-listbox-trigger"
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-controls={listboxId}
          aria-activedescendant={activeOptionId}
          onClick={() => setOpen((current) => !current)}
          onKeyDown={handleKeyDown}
        >
          {SelectedIcon ? <SelectedIcon className="navigation-listbox-icon" strokeWidth={2} /> : null}
          <span className="navigation-listbox-label">{selectedOption?.label ?? emptyLabel}</span>
          <span className="navigation-listbox-chevron" aria-hidden="true">⌄</span>
        </button>
        {open ? (
          <div id={listboxId} className="navigation-listbox-popover" role="listbox" tabIndex={-1}>
            {options.map((option) => {
              const optionIndex = selectableOptions.findIndex((candidate) => candidate.value === option.value);
              const isActive = optionIndex === activeIndex;
              const isSelected = option.value === selectedValue;
              const Icon = iconForKind(option.kind);
              return (
                <div key={`${option.value || 'empty'}:${option.label}`}>
                  <button
                    type="button"
                    role="option"
                    id={optionIndex >= 0 ? `${listboxId}-option-${optionIndex}` : undefined}
                    data-option-index={optionIndex >= 0 ? optionIndex : undefined}
                    aria-selected={isSelected}
                    disabled={option.disabled}
                    className={`navigation-listbox-option ${isActive ? 'is-active' : ''} ${isSelected ? 'is-selected' : ''}`}
                    onMouseEnter={() => {
                      if (optionIndex >= 0) setActiveIndex(optionIndex);
                    }}
                    onClick={() => selectOption(option)}
                  >
                    {Icon ? <Icon className="navigation-listbox-icon" strokeWidth={2} /> : null}
                    <span className="navigation-listbox-label">{option.label}</span>
                  </button>
                </div>
              );
            })}
          </div>
        ) : null}
      </div>
    </div>
  );
}
